/* Self-contained close-up: no dependency on other workspace action handlers. */
(()=>{const button=document.createElement('button');button.type='button';button.hidden=true;button.innerHTML='<span>≈</span>Water';button.setAttribute('aria-label','Open water close-up');let saved;
function restore(){if(!saved)return;for(const [id,v] of Object.entries(saved)){const el=document.getElementById(id);if(!el)continue;el.object3D.position.copy(v.position);el.object3D.scale.copy(v.scale);el.object3D.quaternion.copy(v.quaternion);el.object3D.visible=v.visible}saved=null;button.innerHTML='<span>≈</span>Water';button.setAttribute('aria-pressed','false')}
button.addEventListener('click',()=>{if(saved){restore();return}const env=document.getElementById('environment'),map=document.getElementById('mapRoot'),caption=document.getElementById('destination');if(!env)return;saved={};for(const id of ['environment','mapRoot','destination']){const o=document.getElementById(id)?.object3D;if(o)saved[id]={position:o.position.clone(),scale:o.scale.clone(),quaternion:o.quaternion.clone(),visible:o.visible}}env.object3D.visible=true;env.object3D.position.set(0,1.2,-.8);env.object3D.scale.setScalar(1.1);env.object3D.rotation.set(.22,0,0);if(map)map.object3D.visible=false;if(caption)caption.object3D.visible=false;const camera=document.getElementById('camera'),rig=document.getElementById('rig');if(!document.querySelector('a-scene').is('vr-mode')&&rig){rig.setAttribute('position','0 0 3.8');rig.object3D.rotation.set(0,0,0);const look=camera?.components['look-controls'];if(look){look.yawObject.rotation.y=0;look.pitchObject.rotation.x=-.16}}button.innerHTML='<span>↩</span>Back';button.setAttribute('aria-pressed','true');const status=document.getElementById('status');if(status)status.textContent='Water close-up · Select Back to return.';});const dock=document.getElementById('spatialDock');dock.append(button);dock.addEventListener('click',e=>{if(!button.contains(e.target))restore()},true);window.globiquest.closeWaterView=restore;
})();
